<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$id=(int)($_GET['id']??0);$row=$id?$pdo->query("SELECT * FROM clientes WHERE id=$id")->fetch():null;$pageTitle=$row?'Editar cliente':'Novo cliente';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$nome=trim($_POST['nome']??'');$cpf=trim($_POST['cpf_cnpj']??'');$tel=trim($_POST['telefone']??'');$email=trim($_POST['email']??'');$end=trim($_POST['endereco']??'');$login=trim($_POST['login']??'');$senha=$_POST['senha']??'';if(!$nome||!$login){$error='Nome e login são obrigatórios.';}elseif(!$id&&$senha===''){$error='Informe uma senha para o novo cliente.';}else{try{$n=now();if($id){if($senha!=='')$pdo->prepare('UPDATE clientes SET nome=?,cpf_cnpj=?,telefone=?,email=?,endereco=?,login=?,senha_hash=?,atualizado_em=? WHERE id=?')->execute([$nome,$cpf,$tel,$email,$end,$login,password_hash($senha,PASSWORD_DEFAULT),$n,$id]);else$pdo->prepare('UPDATE clientes SET nome=?,cpf_cnpj=?,telefone=?,email=?,endereco=?,login=?,atualizado_em=? WHERE id=?')->execute([$nome,$cpf,$tel,$email,$end,$login,$n,$id]);log_action('alteração de cliente','clientes',$id);}else{$pdo->prepare('INSERT INTO clientes(nome,cpf_cnpj,telefone,email,endereco,login,senha_hash,ativo,criado_em,atualizado_em) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$nome,$cpf,$tel,$email,$end,$login,password_hash($senha,PASSWORD_DEFAULT),1,$n,$n]);$id=(int)$pdo->lastInsertId();log_action('criação de cliente','clientes',$id);}flash('success','Cliente salvo com sucesso.');redirect('index.php');}catch(Throwable $e){$error='Não foi possível salvar. Verifique se o login já existe.';}}}
include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><div><h1><?=e($pageTitle)?></h1></div><a class="btn secondary" href="index.php">Voltar</a></div><div class="card"><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="field col-6"><label>Nome</label><input name="nome" required value="<?=e($row['nome']??'')?>"></div><div class="field col-3"><label>CPF/CNPJ</label><input name="cpf_cnpj" value="<?=e($row['cpf_cnpj']??'')?>"></div><div class="field col-3"><label>Telefone</label><input name="telefone" value="<?=e($row['telefone']??'')?>"></div><div class="field col-6"><label>E-mail</label><input type="email" name="email" value="<?=e($row['email']??'')?>"></div><div class="field col-6"><label>Login</label><input name="login" required value="<?=e($row['login']??'')?>"></div><div class="field col-12"><label>Endereço</label><input name="endereco" value="<?=e($row['endereco']??'')?>"></div><div class="field col-6"><label>Senha <?= $row?'(opcional)':''?></label><input type="password" name="senha" <?=$row?'':'required'?>></div></div><div class="form-actions"><button class="btn primary">Salvar cliente</button></div></form></div><?php include __DIR__.'/../../includes/footer.php'; ?>
